// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, address caller) public {
        // Assume caller is the owner for the transferOwnership call (though we won't call it in reference)
        vm.assume(initialOwner != address(0));
        // Set initial owner
        vm.prank(address(0)); // owner starts as address(0), so we can transfer to initialOwner
        c.transferOwnership(initialOwner);
        // Now call owned() as the owner
        vm.prank(initialOwner);
        c.owned();
        // Assert that owner did not change
        assertTrue(c.owner() == initialOwner);
    }
}

